$exists = static function (string $table, string $name, string $type) use ($db): bool { $column=$type==='columns'?'column_name':($type==='referential_constraints'?'constraint_name':'index_name');$q=$db->prepare('SELECT COUNT(*) FROM information_schema.'.$type.' WHERE constraint_schema=DATABASE() AND table_name=? AND '.$column.'=?');if($type!=='referential_constraints')$q=$db->prepare('SELECT COUNT(*) FROM information_schema.'.$type.' WHERE table_schema=DATABASE() AND table_name=? AND '.$column.'=?');$q->execute([$table,$name]);return (bool)$q->fetchColumn(); };
$exec = static function (string $sql) use ($db): void { $db->exec($sql); echo "Applied: {$sql}\n"; };

$exec('CREATE TABLE IF NOT EXISTS schema_migrations(version VARCHAR(64) PRIMARY KEY,applied_at DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci');
