$exec('CREATE TABLE IF NOT EXISTS outbox_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_name VARCHAR(96) NOT NULL,event_key CHAR(64) NOT NULL UNIQUE,payload_json JSON NOT NULL,available_at DATETIME(6) NOT NULL,processed_at DATETIME(6) NULL,attempts INT UNSIGNED NOT NULL DEFAULT 0,lease_token CHAR(64) NULL,lease_until DATETIME(6) NULL,last_error VARCHAR(500) NOT NULL DEFAULT \'\',created_at DATETIME(6) NOT NULL,KEY ix_outbox_claim(processed_at,available_at,lease_until,id),KEY ix_outbox_lease(lease_token),KEY ix_outbox_event(event_name,created_at,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci');
$exec('CREATE TABLE IF NOT EXISTS failed_outbox_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,event_id BIGINT UNSIGNED NOT NULL,event_name VARCHAR(96) NOT NULL,event_key CHAR(64) NOT NULL,payload_json JSON NOT NULL,attempts INT UNSIGNED NOT NULL,last_error VARCHAR(500) NOT NULL,failed_at DATETIME(6) NOT NULL,UNIQUE KEY uq_failed_outbox_event(event_id),KEY ix_failed_outbox_name(failed_at,event_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci');
if (!$exists('outbox_events','event_key','columns')) {
    $exec('ALTER TABLE outbox_events ADD COLUMN event_key CHAR(64) NULL AFTER event_name');
    $exec("UPDATE outbox_events SET event_key=SHA2(CONCAT(event_name,'|',payload_json),256) WHERE event_key IS NULL");
    // Identical event name/payload rows are one logical event; retain the oldest row.
    $exec('DELETE duplicate FROM outbox_events AS duplicate INNER JOIN outbox_events AS keeper ON keeper.event_key=duplicate.event_key AND keeper.id<duplicate.id WHERE duplicate.processed_at IS NULL');
    // Retain processed history even when it predates event-key idempotency. These legacy rows
    // need distinct keys to permit the canonical key and its unique index to be introduced.
    $exec("UPDATE outbox_events AS duplicate INNER JOIN (SELECT * FROM (SELECT event_key,MIN(id) AS keeper_id FROM outbox_events GROUP BY event_key HAVING COUNT(*)>1) AS grouped) AS duplicates ON duplicates.event_key=duplicate.event_key SET duplicate.event_key=SHA2(CONCAT(duplicate.event_name,'|',duplicate.payload_json,'|historical:',duplicate.id),256) WHERE duplicate.id<>duplicates.keeper_id");
    $exec('ALTER TABLE outbox_events MODIFY event_key CHAR(64) NOT NULL');
    $exec('ALTER TABLE outbox_events ADD UNIQUE KEY uq_outbox_event_key(event_key)');
}
