    $exec('DELETE FROM outbox_events WHERE id IN (SELECT duplicate_ids.id FROM (SELECT duplicate_row.id FROM outbox_events AS duplicate_row INNER JOIN (SELECT event_name,payload_json,MIN(id) AS keeper_id FROM (SELECT event_name,payload_json,id FROM outbox_events WHERE processed_at IS NULL) AS unprocessed_rows GROUP BY event_name,payload_json) AS keepers ON keepers.event_name=duplicate_row.event_name AND keepers.payload_json=duplicate_row.payload_json WHERE duplicate_row.processed_at IS NULL AND duplicate_row.id<>keepers.keeper_id) AS duplicate_ids)');
    $exec("UPDATE outbox_events AS historical INNER JOIN (SELECT event_name,payload_json,MIN(id) AS lowest_id FROM (SELECT event_name,payload_json,id FROM outbox_events) AS event_rows GROUP BY event_name,payload_json) AS lowest_rows ON lowest_rows.event_name=historical.event_name AND lowest_rows.payload_json=historical.payload_json SET historical.event_key=SHA2(CONCAT(historical.event_name,'|',historical.payload_json,'|historical:',historical.id),256) WHERE historical.id<>lowest_rows.lowest_id");
    $exec("UPDATE outbox_events AS canonical INNER JOIN (SELECT event_name,payload_json,MIN(id) AS lowest_id FROM (SELECT event_name,payload_json,id FROM outbox_events) AS event_rows GROUP BY event_name,payload_json) AS lowest_rows ON lowest_rows.lowest_id=canonical.id SET canonical.event_key=SHA2(CONCAT(canonical.event_name,'|',canonical.payload_json),256)");
